INSERT INTO `videos` (`id`, `title`, `subtitle`, `tagline`, `slug`, `description`, `what_you_will_learn`, `duration`, `audio_file_size`, `publishedAt`, `type`, `category`, `youtube_id`, `realtime_kit`, `resources`) VALUES ('rzoehfxdwc2ldk4xbxgmcdb9', 'Event-Driven Architectures at Wix', NULL, NULL, 'event-driven-architectures-at-wix', 'Natan Silnitsky shares how Wix operates 2,500+ microservices and 70 billion Kafka events per day. We cover when to choose event-driven over RPC, schema evolution with Confluent Schema Registry and protobuf, Kafka cost optimisation, polyglot services, and ZIO on the JVM.', '["When Wix favors events over RPC to decouple services and tolerate failures","How protobuf definitions, linters, and schema registries keep event changes compatible","How Kafka producer, consumer, and admin proxies reduce broker load and bills"]', 2763, 66317724, 1687194000, 'recorded', 'interview', NULL, NULL, '[{"title":"Wix Engineering Blog","type":"url","category":"other","url":"https://www.wix.engineering/"},{"title":"Confluent Schema Registry","type":"url","category":"documentation","url":"https://docs.confluent.io/platform/current/schema-registry/index.html"},{"title":"Natan Silnitsky website","type":"url","category":"other","url":"https://www.natansil.com/"},{"title":"ZIO Scala library","type":"url","category":"code","url":"https://zio.dev/"}]')
--> statement-breakpoint
INSERT INTO `videos` (`id`, `title`, `subtitle`, `tagline`, `slug`, `description`, `what_you_will_learn`, `duration`, `audio_file_size`, `publishedAt`, `type`, `category`, `youtube_id`, `realtime_kit`, `resources`) VALUES ('eoabgl7qts1lx2b0e5wwt3nf', 'Event Sourcing', NULL, NULL, 'event-sourcing', 'In this episode, David interviews Frank, a staff engineer at Personio, a big HR company based out of Germany. Frank has been in the industry for close to 15 years and has worked with various programming languages such as PHP, TypeScript, Kotlin, Java, Go, and Rust.', '["Choose event sourcing when business history matters as much as final state","Use recorded failure events to expose friction hidden by exception-only flows","Plan versioning, projections, and recovery before exposing event streams between services"]', 2729, 65493300, 1684170000, 'recorded', 'interview', NULL, NULL, '[{"title":"EventSauce","type":"url","url":"https://EventSauce.io","category":"code"},{"title":"The Knowledge of Others","type":"url","category":"other"}]')
--> statement-breakpoint
INSERT INTO `videos` (`id`, `title`, `subtitle`, `tagline`, `slug`, `description`, `what_you_will_learn`, `duration`, `audio_file_size`, `publishedAt`, `type`, `category`, `youtube_id`, `realtime_kit`, `resources`) VALUES ('tjd3afh6vpijjepecyc2c9j5', 'InfluxDB 3 & Rust', NULL, NULL, 'influxdb-3-and-rust', 'InfluxDB, a time series database, underwent a major rewrite to create InfluxDB 3.0, also known as IOx. The decision to rewrite the database was driven by the need for strict control over memory management and high performance.', '["Why high-cardinality workloads made the original InfluxDB index increasingly expensive","How Rust, Arrow, Parquet, object storage, and DataFusion shaped InfluxDB 3","Why SQL and InfluxQL are native in InfluxDB 3 while Flux remains unresolved"]', 3368, 80837626, 1699462800, 'recorded', 'interview', NULL, NULL, '[{"title":"Apache Arrow project","type":"url","url":"https://arrow.apache.org/","category":"code"},{"title":"Apache DataFusion project","type":"url","url":"https://datafusion.apache.org/","category":"code"},{"title":"Flux community fork","type":"url","url":"https://github.com/InfluxCommunity/flux","category":"code"},{"title":"HashiCorp license change to BSL","type":"url","url":"https://www.hashicorp.com/blog/hashicorp-adopts-business-source-license","category":"other"}]')
--> statement-breakpoint
INSERT INTO `videos` (`id`, `title`, `subtitle`, `tagline`, `slug`, `description`, `what_you_will_learn`, `duration`, `audio_file_size`, `publishedAt`, `type`, `category`, `youtube_id`, `realtime_kit`, `resources`) VALUES ('rtbqgjn51b7o47pidcfpzog5', 'Is WebAssembly the Future of Cloud Native?', NULL, NULL, 'is-webassembly-the-future-of-cloud-native', 'In this episode, hosts David and Laura, sit down with Laslo Fogas; a self proclaimed WebAssembly sceptic. They discuss the future of Cloud Native and improving the broken developer experience.', '["Why container-based development strains local feedback loops on Mac and Windows","How the component model trades POSIX access for explicit sandboxed capabilities","Where WebAssembly can complement Kubernetes through lightweight runtimes and extension points"]', 2588, 62100934, 1689958800, 'recorded', 'interview', NULL, NULL, '[{"title":"kwasm","type":"url","url":"https://kwasm.sh/","category":"code"},{"title":"WebAssembly","type":"url","url":"https://webassembly.org/","category":"documentation"},{"title":"Gimlet","type":"url","url":"https://gimlet.io/","category":"other"}]')
--> statement-breakpoint
INSERT INTO `videos` (`id`, `title`, `subtitle`, `tagline`, `slug`, `description`, `what_you_will_learn`, `duration`, `audio_file_size`, `publishedAt`, `type`, `category`, `youtube_id`, `realtime_kit`, `resources`) VALUES ('ratw2atcqa376ktfpvj2joo4', 'Kubernetes Security with Identity & OIDC', NULL, NULL, 'kubernetes-security-with-identity-and-oidc', 'Marc Boorshtein, CTO of Tremolo Security, explains why long-lived kubeconfig certificates are an anti-pattern, how OIDC and impersonation deliver revocable cluster access, and how workflow identity via OIDC JWTs replaces static service account tokens in CI/CD pipelines.', '["Why long-lived kubeconfig certificates should be reserved for break-glass access","How OIDC impersonation maps GitHub workflow identities to Kubernetes RBAC","Why supply chain signing depends on trusted identities, not just cryptographic keys"]', 2326, 55827785, 1685379600, 'recorded', 'interview', NULL, NULL, '[{"title":"OpenUnison","type":"url","url":"https://openunison.github.io/","category":"code"},{"title":"CICD Proxy","type":"url","url":"https://cicdproxy.github.io/","category":"code"},{"title":"Kubernetes and the Enterprise","type":"url","category":"other"},{"title":"Kubernetes Security Days talk on certificate authentication","type":"url","category":"other"},{"title":"CICD Proxy Helm charts for kube-oidc-proxy impersonation","type":"url","category":"code"}]')
